"""Curriculum labels and action schema must remain train-only."""
import json
from pathlib import Path

import pytest

from scripts.build_stop_curriculum import canonical_action, curriculum
from sidra.agent import SearchAgent
from sidra.io import load_dataset,save_jsonl
from sidra.policies import FixtureMultiHopPolicy
from sidra.sft import build_sft_examples


def prepared_train(fixture_dir, tmp_path):
    # Fixture gold is TRAIN-only, and generated by a deterministic verified
    # smoke policy. These tests do NOT benchmark real model accuracy.
    from sidra.schema import Question
    from sidra.metrics import score_trace
    docs,qs=load_dataset(fixture_dir)
    train=[q for q in qs if q.split=="train"][:9]
    assert train
    data=tmp_path/"train"
    data.mkdir()
    save_jsonl(data/"documents.jsonl",[d.__dict__ for d in docs])
    save_jsonl(data/"questions.jsonl",[q.__dict__ for q in train])
    agent=SearchAgent(docs,FixtureMultiHopPolicy())
    traces=[agent.run(q).as_dict() for q in train]
    save_jsonl(tmp_path/"traces.jsonl",traces)
    source=tmp_path/"source_sft.jsonl"
    build_sft_examples(data,tmp_path/"traces.jsonl",source)
    manifest=tmp_path/"DEV_MANIFEST.json"
    manifest.write_text(json.dumps({"pilot":{"selected_ids":["separate-dev-a"]},
                                    "heldout":{"selected_ids":["separate-dev-b"]}}))
    return data,source,manifest


def test_minimal_action_fields():
    assert canonical_action({"kind":"search","query":"Z","answer":"",
                             "citations":[],"doc_id":""})=={"kind":"search","query":"Z"}
    assert canonical_action({"kind":"read","doc_id":"d","query":""})=={"kind":"read","doc_id":"d"}
    assert canonical_action({"kind":"finish","answer":"","citations":[]})=={
        "kind":"finish","answer":"","citations":[]}
    with pytest.raises(ValueError):
        canonical_action({"kind":"search","query":""})


def test_train_only_format_vs_stop_curriculum(fixture_dir,tmp_path):
    data,source,dev=prepared_train(fixture_dir,tmp_path)
    fmt=curriculum(source,data,dev,tmp_path/"format",mode="format",seed=43)
    st=curriculum(source,data,dev,tmp_path/"stop",mode="stop",seed=43)
    assert fmt["train_only"] and st["train_only"]
    assert fmt["total_source_actions"]==fmt["output_total_actions"]
    assert st["output_total_actions"]>fmt["output_total_actions"]
    assert st["output_action_counts"]["finish"]>fmt["output_action_counts"]["finish"]
    assert st["output_action_counts"]["read"]==fmt["output_action_counts"]["read"]
    assert st["output_action_counts"]["search"]==fmt["output_action_counts"]["search"]
    r=[json.loads(s) for s in (tmp_path/"stop/actions.jsonl").read_text().splitlines()]
    assert r
    for row in r:
        prompt=row["prompt"]
        user=json.loads(prompt[1]["content"])
        action=json.loads(row["completion"][0]["content"])
        assert user["remaining_steps"]>=1
        assert set(action)==(
            {"kind","query"} if action["kind"]=="search" else
            {"kind","doc_id"} if action["kind"]=="read" else
            {"kind","answer","citations"})
        assert "gold_answer" not in prompt[1]["content"]
        assert "supporting_doc_ids" not in prompt[1]["content"]
    with pytest.raises(FileExistsError):
        curriculum(source,data,dev,tmp_path/"stop",mode="stop")


def test_dev_overlap_fails_closed(fixture_dir,tmp_path):
    data,source,dev=prepared_train(fixture_dir,tmp_path)
    first=json.loads(source.read_text().splitlines()[0])["question_id"]
    dev.write_text(json.dumps({"pilot":{"selected_ids":[first]},
                               "heldout":{"selected_ids":[]}}))
    with pytest.raises(ValueError,match="overlap"):
        curriculum(source,data,dev,tmp_path/"must_not_exist",mode="format")
    assert not (tmp_path/"must_not_exist").exists()


def test_no_development_set_actions_accepted(fixture_dir,tmp_path):
    data,source,dev=prepared_train(fixture_dir,tmp_path)
    rows=[json.loads(s) for s in source.read_text().splitlines()]
    rows[0]["question_id"]="fake-dev"
    save_jsonl(tmp_path/"source_with_dev.jsonl",rows)
    with pytest.raises(ValueError,match="train-only"):
        curriculum(tmp_path/"source_with_dev.jsonl",data,dev,tmp_path/"out",
                   mode="stop")
